  "revision_action": "initial",
  "supportive_card_ids": [
    "C47", "C17", "C29", "C04", "C08", "C15", "C46", "C42", "C10", "C21", "C03", "C23", "C27", "C33", "C18"
  ],
  "contradictory_card_ids": [
    "C38", "C02", "C28", "C40", "C48", "C01"
  ],
  "prediction_basis_card_ids": [
    "C47", "C17", "C29", "C04", "C08", "C15", "C46", "C42", "C10", "C21", "C18"
  ],
  "claims": [
    {
      "claim": "2-Methoxyestradiol, an estradiol analogue with the same phenolic A-ring and steroid core, has measured oral bioavailability of only 1–2% in patients, attributed to low aqueous solubility and extensive first-pass metabolism; this is the closest direct low-F precedent for the estradiol cypionate query.",
      "card_ids": ["C47", "C17", "C29"]
    },
    {
      "claim": "Danazol, a highly lipophilic steroid, has absolute oral bioavailability of 11–19% in fasted humans across capsule and solution formulations, all below the 20% threshold.",
      "card_ids": ["C04", "C08", "C15", "C46"]
    },
    {
      "claim": "Progesterone clinical records consistently report poor/low oral bioavailability (~5% to <10%) due to limited solubility and gut/liver metabolism.",
      "card_ids": ["C10", "C21", "C42", "C03", "C23", "C27", "C33"]
    },
    {
      "claim": "The single predicted 34% oral F for progesterone is an in vitro-based prediction, not a measured outcome, and is outweighed by the clinical low-F records.",
      "card_ids": ["C01"]
    },
    {
      "claim": "Estramustine phosphate, an estradiol prodrug, has records reporting 34.9–56.2% oral F, but direct measurement found no parent drug in plasma after oral dosing, indicating those values reflect active metabolites rather than parent bioavailability; this limits its use as a high-F precedent for the query ester.",
      "card_ids": ["C38", "C02", "C28", "C40", "C48", "C18"]
    },
    {
      "claim": "High-F records for ethinyl estradiol (51%) and NOMAC (~63%) involve different steroids and do not transfer to the estradiol cypionate query.",
      "card_ids": ["C14", "C43"]
    },
    {
      "claim": "The query's physicochemical prior (logD 6.13, one phenol, one ester, no basic center) predicts very poor aqueous solubility, consistent with the low-F steroid records; no affirmative measured evidence supports F≥20% for estradiol cypionate.",
      "card_ids": ["C29", "C42"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C47", "C17", "C29", "C04", "C08", "C15", "C46", "C42", "C18"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate itself is present in the supplied records.",
    "Dose, formulation, and prandial state for the query are unspecified; oral F of lipophilic steroids is highly formulation-dependent.",
    "The estramustine phosphate high-F records are ambiguous as to whether they measure parent prodrug or active metabolites; direct parent measurement indicates very low parent F.",
    "High-F records for ethinyl estradiol and NOMAC involve different steroids and are not transferable.",
    "The ester prodrug may be hydrolyzed before absorption; the bioavailability of the active estradiol moiety versus the parent ester is not resolved."
  ],
  "decision_summary": "Predicted low: the closest steroid analogues with measured oral F (2-methoxyestradiol 1–2%, danazol 11–19%, progesterone <10%) all fall below 20%, and the query's very high logD predicts poor aqueous solubility; the only high-F records are for different steroids or active metabolites and do not transfer."
}

